{
  "items": [
    {
      "name": "roth_3ap_theorem_nat",
      "module_name": "Mathlib.Combinatorics.Additive.Corner.Roth",
      "kind": "theorem",
      "type": "∀ {n : ℕ} (ε : ℝ), 0 < ε → cornersTheoremBound (ε / 3) ≤ n → ∀ A ⊆ Finset.range n, ε * ↑n ≤ ↑A.card → ¬ThreeAPFree ↑A"
    },
    {
      "name": "roth_3ap_theorem",
      "module_name": "Mathlib.Combinatorics.Additive.Corner.Roth",
      "kind": "theorem",
      "type": "∀ {G : Type u_1} [inst : AddCommGroup G] [inst_1 : Fintype G] (ε : ℝ),\n  0 < ε → cornersTheoremBound ε ≤ Fintype.card G → ∀ (A : Finset G), ε * ↑(Fintype.card G) ≤ ↑A.card → ¬ThreeAPFree ↑A"
    },
    {
      "name": "rothNumberNat",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "definition",
      "type": "ℕ →o ℕ"
    },
    {
      "name": "Behrend.roth_lower_bound",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ ↑(rothNumberNat N)"
    },
    {
      "name": "ThreeAPFree.le_rothNumberNat",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "theorem",
      "type": "∀ {k n : ℕ} (s : Finset ℕ), ThreeAPFree ↑s → (∀ x ∈ s, x < n) → s.card = k → k ≤ rothNumberNat n"
    },
    {
      "name": "Behrend.bound_aux'",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ (n d : ℕ), ↑(d ^ n) / ↑(n * d ^ 2) ≤ ↑(rothNumberNat ((2 * d - 1) ^ n))"
    }
  ]
}
